#pragma once
#include "WavetableLibrary.h"
#include "PresetLibrary.h"
namespace noctrl {
// Portable FX-only documents. Slot IDs are deliberately not persisted: a preset
// is remapped into the destination rack without changing synth or other buses.
struct FxLibrary {
 static juce::StringArray keys(){using namespace juce;StringArray out{"wet","enabled","customShape","preCut","knee","multiband","crossLow","crossHigh"};for(int i=0;i<16;++i)out.add("gate"+String(i));for(int i=0;i<8;++i)out.add("p"+String(i));for(int i=0;i<17;++i)out.add("shape"+String(i));for(int i=0;i<3;++i){out.add("bandGain"+String(i));out.add("bandThreshold"+String(i));}return out;}
 static juce::var defaults(int type){using namespace juce;auto* params=new DynamicObject();for(auto key:keys()){float v=0;if(key=="wet"||key=="enabled")v=1;else if(key.startsWith("p")&&key.substring(1).containsOnly("0123456789"))v=.5f;else if(key.startsWith("gate"))v=trancegateDefault(key.substring(4).getIntValue());else if(key.startsWith("shape"))v=-1+key.substring(5).getIntValue()/8.f;else if(key=="preCut")v=20000;else if(key=="crossLow")v=250;else if(key=="crossHigh")v=3500;params->setProperty(key,v);}auto& def=fxDefinitions()[(size_t)type];for(int i=0;i<(int)def.controls.size();++i)params->setProperty("p"+String(i),def.controls[(size_t)i].to(def.controls[(size_t)i].initial));params->setProperty("wet",def.wet);return var(params);}
 static juce::var document(juce::Array<juce::var> effects,bool single){auto* object=new juce::DynamicObject();object->setProperty("format","NEXUM.FX");object->setProperty("version",1);object->setProperty("scope",single?"effect":"chain");object->setProperty("effects",effects);return juce::var(object);}
 static juce::var capture(SynthProcessor& p,int bus,int slot=-1){using namespace juce;Array<var> effects;for(auto& entry:p.rack()->entries)if(entry.bus==bus&&(slot<0||entry.slot==slot)){auto* object=new DynamicObject();object->setProperty("type",entry.type);auto* params=new DynamicObject();for(auto key:keys())params->setProperty(key,p.value(fxId(entry.slot,key)));object->setProperty("params",var(params));object->setProperty("ir",entry.ir.getSize()?entry.ir.toBase64Encoding():String());object->setProperty("irName",entry.irName);effects.add(var(object));}return document(effects,slot>=0);}
 static juce::Result validate(const juce::var& doc){using namespace juce;if(doc.getProperty("format",{}).toString()!="NEXUM.FX"||(int)doc.getProperty("version",0)!=1)return Result::fail("Unsupported FX preset format.");auto scope=doc.getProperty("scope",{}).toString();auto effects=doc.getProperty("effects",{});auto* list=effects.getArray();if(!list||list->isEmpty()||list->size()>64||(scope!="effect"&&scope!="chain")||(scope=="effect"&&list->size()!=1))return Result::fail("Select a valid single effect or chain (1-64 effects).");auto allowed=keys();int64 total=0;for(auto& effect:*list){auto typeValue=effect.getProperty("type",-1);int type=(int)typeValue;if((!typeValue.isInt()&&!typeValue.isInt64())||type<0||type>=(int)fxDefinitions().size())return Result::fail("Unknown effect type.");auto params=effect.getProperty("params",{});if(!params.isObject())return Result::fail("Missing effect settings.");for(auto& item:params.getDynamicObject()->getProperties()){auto key=item.name.toString();if(!allowed.contains(key)||(!item.value.isInt()&&!item.value.isInt64()&&!item.value.isDouble()&&!item.value.isBool())||!std::isfinite((double)item.value))return Result::fail("Invalid effect parameter.");}auto encoded=effect.getProperty("ir",{}).toString();total+=encoded.length();if(encoded.length()>24*1024*1024||total>64*1024*1024)return Result::fail("FX preset contains too much impulse-response data.");if(encoded.isNotEmpty()){MemoryBlock bytes;if(type!=3||!bytes.fromBase64Encoding(encoded)||bytes.getSize()>16*1024*1024)return Result::fail("Invalid impulse response.");AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(std::make_unique<MemoryInputStream>(bytes,false)));if(!reader||reader->lengthInSamples<=0||reader->sampleRate<=0)return Result::fail("Impulse response cannot be decoded.");}}return Result::ok();}
 static juce::Result read(juce::File file,juce::var& doc){if(!file.existsAsFile()||file.getSize()>72LL*1024*1024)return juce::Result::fail("FX preset is missing or too large.");auto result=juce::JSON::parse(file.loadFileAsString(),doc);return result.failed()?result:validate(doc);}
 static juce::Result writeJson(juce::File file,const juce::var& doc){juce::TemporaryFile temporary(file);if(file.getParentDirectory().createDirectory().failed()||!temporary.getFile().replaceWithText(juce::JSON::toString(doc,true))||!temporary.overwriteTargetFileWithTemporary())return juce::Result::fail("Could not save FX preset.");return juce::Result::ok();}
 static juce::Result save(juce::File folder,const PresetMetadata& values,juce::var doc,juce::File& saved){auto name=values.name.trim();if(name.isEmpty()||name.startsWithChar('.')||name.length()>100||juce::File::createLegalFileName(name)!=name)return juce::Result::fail("Choose a valid preset name.");auto result=validate(doc);if(result.failed())return result;doc.getDynamicObject()->setProperty("metadata",values.toJson());saved=folder.getChildFile(name+".ncfx").getNonexistentSibling();return writeJson(saved,doc);}
 static juce::Result apply(SynthProcessor& p,const juce::var& doc,int bus){using namespace juce;auto result=validate(doc);if(result.failed())return result;if(bus<0||bus>12||(bus>=3&&!p.rack()->connections[bus-3])||(p.effectOnly&&bus!=0))return Result::fail("Invalid target rack.");bool replace=doc.getProperty("scope",{}).toString()=="chain";auto list=*doc.getProperty("effects",{}).getArray();auto next=std::make_shared<FxRackState>();std::array<bool,64> used{},clear{};auto previous=p.rack();next->connections=previous->connections;next->cableColours=previous->cableColours;for(auto& entry:previous->entries){if(replace&&entry.bus==bus)clear[entry.slot]=true;else{next->entries.push_back(entry);used[entry.slot]=true;}}if(next->entries.size()+list.size()>64)return Result::fail("The FX rack has no free slots. No settings were changed.");struct Pending{FxEntry entry;var params;};std::vector<Pending> pending;for(auto& object:list){int slot=0;while(slot<64&&used[slot])++slot;used[slot]=true;clear[slot]=true;int type=(int)object.getProperty("type",0);auto params=defaults(type);auto source=object.getProperty("params",{});for(auto& item:source.getDynamicObject()->getProperties()){auto key=item.name.toString();auto* parameter=p.state.getParameter(fxId(slot,key));float value=(float)item.value;auto range=parameter->getNormalisableRange();if(value<range.start||value>range.end)return Result::fail("FX setting is outside its valid range. No settings were changed.");params.getDynamicObject()->setProperty(key,value);}FxEntry entry{slot,type,bus,{},{}};entry.ir.fromBase64Encoding(object.getProperty("ir",{}).toString());entry.irName=object.getProperty("irName",{}).toString();pending.push_back({entry,params});next->entries.push_back(entry);}
  const ScopedLock callbackLock(p.getCallbackLock());if(p.rack()!=previous)return Result::fail("The rack changed while loading. Please retry.");auto belongs=[&](String id){if(!id.startsWith("rack"))return false;int slot=id.substring(4).getIntValue()-1;return slot>=0&&slot<64&&clear[slot];};auto macros=std::make_shared<MacroRouting>(*p.macros());macros->links.erase(std::remove_if(macros->links.begin(),macros->links.end(),[&](auto& link){return belongs(link.target);}),macros->links.end());std::atomic_store(&p.macroRouting,std::shared_ptr<const MacroRouting>(macros));auto live=std::make_shared<LiveModRouting>(*p.liveMods());live->links.erase(std::remove_if(live->links.begin(),live->links.end(),[&](auto& link){return belongs(link.target);}),live->links.end());p.publishLiveMods(live);
  for(auto& item:pending)for(auto& parameter:item.params.getDynamicObject()->getProperties())p.set(fxId(item.entry.slot,parameter.name.toString()),(float)parameter.value);std::atomic_store(&p.fxRackState,std::shared_ptr<const FxRackState>(next));p.rebuildFxRack();return Result::ok();}
 static juce::String summary(const juce::var& doc){juce::StringArray names;if(auto* list=doc.getProperty("effects",{}).getArray())for(auto& entry:*list){int type=(int)entry.getProperty("type",-1);if(type>=0&&type<(int)fxDefinitions().size())names.add(fxDefinitions()[(size_t)type].name);}return names.joinIntoString("  >  ");}
 static juce::Result seed(juce::File root){using namespace juce;auto marker=root.getChildFile(".initialized");auto savedVersion=marker.loadFileAsString().trim();int known=marker.exists()?(savedVersion.startsWith("NEXUM.FX.DEFAULTS:")?savedVersion.fromFirstOccurrenceOf(":",false,false).getIntValue():16):0;if(known>=(int)fxDefinitions().size())return Result::ok();for(int type=jmax(0,known);type<(int)fxDefinitions().size();++type){auto* effect=new DynamicObject();effect->setProperty("type",type);effect->setProperty("params",defaults(type));Array<var> list;list.add(var(effect));PresetMetadata meta;meta.name=fxDefinitions()[(size_t)type].name.replace(" / "," - ").replace("/","-");meta.author="NEXUM";meta.category=type==16?"Rhythmic":type==0?"Pitch":type==5?"Distortion":type==2?"Dynamics":type==6||type==7?"Filter & EQ":type>=12?"Utility & Routing":type==3||type==4||type==11?"Space & Delay":"Modulation";meta.description="Default "+fxDefinitions()[(size_t)type].name+" settings";File saved;auto folder=root.getChildFile("Effekte");if(folder.getChildFile(meta.name+".ncfx").exists())continue;auto result=save(folder,meta,document(list,true),saved);if(result.failed())return result;}return root.getChildFile(".initialized").replaceWithText("NEXUM.FX.DEFAULTS:"+String(fxDefinitions().size()))?Result::ok():Result::fail("Could not initialise FX Library.");}
 static WavetableLibrary::ImportResult importPack(juce::File source,juce::File root){using namespace juce;WavetableLibrary::ImportResult result;auto stage=root.getChildFile(".import-"+Uuid().toString());if(stage.createDirectory().failed()){result.error="Could not prepare FX import.";return result;}auto add=[&](String relative,const String& content){var doc;if(JSON::parse(content,doc).failed()||validate(doc).failed()){++result.skipped;return;}auto target=stage.getChildFile(relative);if(!target.isAChildOf(stage)||writeJson(target,doc).failed()){result.error="Could not import FX preset.";return;}++result.added;};if(source.hasFileExtension("zip")){ZipFile zip(source);int64 total=0;if(zip.getNumEntries()>4096)result.error="FX archive contains too many entries.";for(int i=0;result.error.isEmpty()&&i<zip.getNumEntries();++i){auto* entry=zip.getEntry(i);auto path=entry->filename.replaceCharacter('\\','/');if(File::isAbsolutePath(path)||path.containsChar(':')||StringArray::fromTokens(path,"/","").contains("..")||entry->isSymbolicLink){result.error="Invalid FX archive path.";break;}if(!path.endsWithIgnoreCase(".ncfx"))continue;total+=entry->uncompressedSize;if(entry->uncompressedSize<0||total>72LL*1024*1024){result.error="FX archive is too large.";break;}std::unique_ptr<InputStream> input(zip.createStreamForEntry(i));if(!input){result.error="Could not read FX archive.";break;}var doc;JSON::parse(input->readEntireStreamAsString(),doc);int sideIndex=zip.getIndexOfFileName(path+".asset.json");if(doc.isObject()&&sideIndex>=0&&zip.getEntry(sideIndex)->uncompressedSize>=0&&zip.getEntry(sideIndex)->uncompressedSize<1024*1024){std::unique_ptr<InputStream> side(zip.createStreamForEntry(sideIndex));if(side){auto meta=JSON::parse(side->readEntireStreamAsString());if(meta.isObject())doc.getDynamicObject()->setProperty("metadata",meta);}}add(path,JSON::toString(doc));}}else{auto files=source.isDirectory()?source.findChildFiles(File::findFiles,true,"*.ncfx"):Array<File>();if(!source.isDirectory()&&source.hasFileExtension("ncfx"))files.add(source);if(files.size()>4096)result.error="Too many FX presets.";int64 total=0;for(auto& file:files){if(result.error.isNotEmpty())break;total+=file.getSize();if(file.isSymbolicLink()||total>72LL*1024*1024){result.error="FX import is too large or contains a symbolic link.";break;}var doc;auto valid=read(file,doc);if(valid.failed()){++result.skipped;continue;}auto sidecar=file.getSiblingFile(file.getFileName()+".asset.json");if(sidecar.existsAsFile()&&sidecar.getSize()<1024*1024){auto meta=JSON::parse(sidecar.loadFileAsString());if(meta.isObject())doc.getDynamicObject()->setProperty("metadata",meta);}add(source.isDirectory()?file.getRelativePathFrom(source):file.getFileName(),JSON::toString(doc));}}if(result.added==0&&result.error.isEmpty())result.error="No valid .ncfx presets found.";if(result.error.isEmpty()){result.folder=root.getChildFile(File::createLegalFileName(source.isDirectory()?source.getFileName():source.getFileNameWithoutExtension())).getNonexistentSibling();if(!stage.moveFileTo(result.folder))result.error="Could not finish FX import.";}if(result.error.isNotEmpty()){stage.deleteRecursively();result.added=0;}return result;}
};
}
